-- case: scatter_color
SELECT * FROM (SELECT * FROM pts) AS "__schema__" LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "g" AS "__ggsql_aes_fill__", "a" AS "__ggsql_aes_pos1__", "b" AS "__ggsql_aes_pos2__", "g" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM pts) AS "__ggsql_src__") SELECT MIN("a") AS "a", MIN("b") AS "b", MIN("g") AS "g" FROM "__ggsql_source__" UNION ALL SELECT MAX("a") AS "a", MAX("b") AS "b", MAX("g") AS "g" FROM "__ggsql_source__";
