SELECT *, "__ggsql_stat_pos2" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM (WITH "__ggsql_stat_src__" AS (SELECT *, "grp" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM line_data) AS "__ggsql_src__") SELECT "__ggsql_aes_pos1__", AVG("__ggsql_aes_pos2__") AS "__ggsql_stat_pos2" FROM "__ggsql_stat_src__" AS "__ggsql_qt__" GROUP BY "__ggsql_aes_pos1__") AS "__ggsql_ord__" ORDER BY "__ggsql_aes_pos1__") AS "__ggsql_stat__";

-- case: density_grouped
SELECT * FROM (SELECT * FROM dens_data) AS "__schema__" LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") SELECT MIN("value") AS "value", MIN("grp") AS "grp" FROM "__ggsql_source__" UNION ALL SELECT MAX("value") AS "value", MAX("grp") AS "grp" FROM "__ggsql_source__";
SELECT *, "__ggsql_stat_pos1" AS "__ggsql_aes_pos1__", "__ggsql_stat_density" AS "__ggsql_aes_pos2__" FROM (WITH RECURSIVE bandwidth AS ( SELECT 0.9 * LEAST(SQRT(AVG("__ggsql_aes_pos1__"*"__ggsql_aes_pos1__") - AVG("__ggsql_aes_pos1__")*AVG("__ggsql_aes_pos1__")), ((SELECT MAX(CASE WHEN rn = 1 + FLOOR(0.75 * (cnt - 1)) THEN __val END) + (MAX(CASE WHEN rn = 1 + CEIL(0.75 * (cnt - 1)) THEN __val END) - MAX(CASE WHEN rn = 1 + FLOOR(0.75 * (cnt - 1)) THEN __val END)) * MAX(0.75 * (cnt - 1) - FLOOR(0.75 * (cnt - 1))) FROM (SELECT "__ggsql_aes_pos1__" AS __val, ROW_NUMBER() OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ORDER BY "__ggsql_aes_pos1__") AS rn, COUNT(*) OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ) AS cnt, "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__") AND ("__ggsql_tile__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__")) - (SELECT MAX(CASE WHEN rn = 1 + FLOOR(0.25 * (cnt - 1)) THEN __val END) + (MAX(CASE WHEN rn = 1 + CEIL(0.25 * (cnt - 1)) THEN __val END) - MAX(CASE WHEN rn = 1 + FLOOR(0.25 * (cnt - 1)) THEN __val END)) * MAX(0.25 * (cnt - 1) - FLOOR(0.25 * (cnt - 1))) FROM (SELECT "__ggsql_aes_pos1__" AS __val, ROW_NUMBER() OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ORDER BY "__ggsql_aes_pos1__") AS rn, COUNT(*) OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ) AS cnt, "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__") AND ("__ggsql_tile__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__"))) / 1.34) * POWER(1.0 * COUNT(*), -0.2) AS bw, "__ggsql_aes_fill__", "__ggsql_aes_stroke__", MIN("__ggsql_aes_pos1__") AS x_min, MAX("__ggsql_aes_pos1__") AS x_max FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_qt__" WHERE "__ggsql_aes_pos1__" IS NOT NULL GROUP BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ), data AS ( SELECT "__ggsql_aes_fill__", "__ggsql_aes_stroke__", "__ggsql_aes_pos1__" AS val, 1.0 AS weight FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_data__" WHERE "__ggsql_aes_pos1__" IS NOT NULL ), "__ggsql_seq__"(n) AS (SELECT CAST(t AS DOUBLE) AS n FROM UNNEST(SEQUENCE(0, 512 - 1)) AS u(t)), global_range AS ( SELECT MIN(x_min) AS min, MAX(x_max) AS max, 3 * MAX(bw) AS expansion FROM bandwidth ), grid AS ( SELECT "__ggsql_aes_fill__", "__ggsql_aes_stroke__", ("__ggsql_global__".min - "__ggsql_global__".expansion) + (seq.n * (("__ggsql_global__".max - "__ggsql_global__".min) + 2 * "__ggsql_global__".expansion) / 511) AS x FROM global_range AS "__ggsql_global__" CROSS JOIN "__ggsql_seq__" AS seq CROSS JOIN (SELECT DISTINCT "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM bandwidth) AS "__ggsql_groups__" ) SELECT "__ggsql_stat_pos1", "__ggsql_aes_fill__", "__ggsql_aes_stroke__", "__ggsql_stat_intensity", "__ggsql_stat_intensity" / "__norm" AS "__ggsql_stat_density" FROM ( SELECT grid.x AS "__ggsql_stat_pos1", grid."__ggsql_aes_fill__" AS "__ggsql_aes_fill__", grid."__ggsql_aes_stroke__" AS "__ggsql_aes_stroke__", SUM(data.weight * ((EXP(-0.5 * (grid.x - data.val) * (grid.x - data.val) / (bandwidth.bw * bandwidth.bw))) * 0.3989422804014327)) / MIN(bandwidth.bw) AS "__ggsql_stat_intensity", SUM(data.weight) AS "__norm" FROM data INNER JOIN bandwidth ON (data."__ggsql_aes_fill__" IS NOT DISTINCT FROM bandwidth."__ggsql_aes_fill__") AND (data."__ggsql_aes_stroke__" IS NOT DISTINCT FROM bandwidth."__ggsql_aes_stroke__") INNER JOIN grid ON (grid."__ggsql_aes_fill__" IS NOT DISTINCT FROM data."__ggsql_aes_fill__") AND (grid."__ggsql_aes_stroke__" IS NOT DISTINCT FROM data."__ggsql_aes_stroke__") GROUP BY grid.x, grid."__ggsql_aes_fill__", grid."__ggsql_aes_stroke__" ) AS "__ggsql_kde__") AS "__ggsql_stat__";

-- case: line_temporal
DROP TABLE IF EXISTS "__ggsql_global_<session>__";
CREATE TEMP TABLE "__ggsql_global_<session>__" AS SELECT * FROM ts_data;
SELECT * FROM (SELECT * FROM "__ggsql_global_<session>__") AS "__schema__" LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "day" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM "__ggsql_global_<session>__") AS "__ggsql_src__") SELECT MIN("day") AS "day", MIN("value") AS "value" FROM "__ggsql_source__" UNION ALL SELECT MAX("day") AS "day", MAX("value") AS "value" FROM "__ggsql_source__";
SELECT *, "day" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM "__ggsql_global_<session>__") AS "__ggsql_src__" ORDER BY "__ggsql_aes_pos1__";

