SELECT *, "__ggsql_stat_pos2" AS "__ggsql_aes_pos2__", "__ggsql_stat_density" AS "__ggsql_aes_offset__" FROM (WITH RECURSIVE bandwidth AS ( SELECT 0.9 * LEAST(SQRT(AVG("__ggsql_aes_pos2__"*"__ggsql_aes_pos2__") - AVG("__ggsql_aes_pos2__")*AVG("__ggsql_aes_pos2__")), ((SELECT MAX(CASE WHEN rn = 1 + FLOOR(0.75 * (cnt - 1)) THEN __val END) + (MAX(CASE WHEN rn = 1 + CEIL(0.75 * (cnt - 1)) THEN __val END) - MAX(CASE WHEN rn = 1 + FLOOR(0.75 * (cnt - 1)) THEN __val END)) * MAX(0.75 * (cnt - 1) - FLOOR(0.75 * (cnt - 1))) FROM (SELECT "__ggsql_aes_pos2__" AS __val, ROW_NUMBER() OVER (PARTITION BY "__ggsql_aes_pos1__" ORDER BY "__ggsql_aes_pos2__") AS rn, COUNT(*) OVER (PARTITION BY "__ggsql_aes_pos1__" ) AS cnt, "__ggsql_aes_pos1__" FROM (SELECT *, "g" AS "__ggsql_aes_pos1__", "v" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM vio_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos2__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_pos1__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_pos1__")) - (SELECT MAX(CASE WHEN rn = 1 + FLOOR(0.25 * (cnt - 1)) THEN __val END) + (MAX(CASE WHEN rn = 1 + CEIL(0.25 * (cnt - 1)) THEN __val END) - MAX(CASE WHEN rn = 1 + FLOOR(0.25 * (cnt - 1)) THEN __val END)) * MAX(0.25 * (cnt - 1) - FLOOR(0.25 * (cnt - 1))) FROM (SELECT "__ggsql_aes_pos2__" AS __val, ROW_NUMBER() OVER (PARTITION BY "__ggsql_aes_pos1__" ORDER BY "__ggsql_aes_pos2__") AS rn, COUNT(*) OVER (PARTITION BY "__ggsql_aes_pos1__" ) AS cnt, "__ggsql_aes_pos1__" FROM (SELECT *, "g" AS "__ggsql_aes_pos1__", "v" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM vio_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos2__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_pos1__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_pos1__"))) / 1.34) * POWER(1.0 * COUNT(*), -0.2) AS bw, "__ggsql_aes_pos1__", MIN("__ggsql_aes_pos2__") AS x_min, MAX("__ggsql_aes_pos2__") AS x_max FROM (SELECT *, "g" AS "__ggsql_aes_pos1__", "v" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM vio_data) AS "__ggsql_src__") AS "__ggsql_qt__" WHERE "__ggsql_aes_pos2__" IS NOT NULL GROUP BY "__ggsql_aes_pos1__" ), data AS ( SELECT "__ggsql_aes_pos1__", "__ggsql_aes_pos2__" AS val, 1.0 AS weight FROM (SELECT *, "g" AS "__ggsql_aes_pos1__", "v" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM vio_data) AS "__ggsql_src__") AS "__ggsql_data__" WHERE "__ggsql_aes_pos2__" IS NOT NULL ), "__ggsql_seq__"(n) AS (SELECT CAST(t AS DOUBLE) AS n FROM UNNEST(SEQUENCE(0, 512 - 1)) AS u(t)), global_range AS ( SELECT MIN(x_min) AS min, MAX(x_max) AS max, 3 * MAX(bw) AS expansion FROM bandwidth ), full_grid AS ( SELECT "__ggsql_aes_pos1__", ("__ggsql_global__".min - "__ggsql_global__".expansion) + (seq.n * (("__ggsql_global__".max - "__ggsql_global__".min) + 2 * "__ggsql_global__".expansion) / 511) AS x FROM global_range AS "__ggsql_global__" CROSS JOIN "__ggsql_seq__" AS seq CROSS JOIN (SELECT DISTINCT "__ggsql_aes_pos1__" FROM bandwidth) AS "__ggsql_groups__" ), grid AS ( SELECT full_grid."__ggsql_aes_pos1__" AS "__ggsql_aes_pos1__", full_grid.x FROM full_grid INNER JOIN bandwidth ON (full_grid."__ggsql_aes_pos1__" IS NOT DISTINCT FROM bandwidth."__ggsql_aes_pos1__") WHERE full_grid.x >= bandwidth.x_min - 3 * bandwidth.bw AND full_grid.x <= bandwidth.x_max + 3 * bandwidth.bw ) SELECT "__ggsql_stat_pos2", "__ggsql_aes_pos1__", "__ggsql_stat_intensity", "__ggsql_stat_intensity" / "__norm" AS "__ggsql_stat_density" FROM ( SELECT grid.x AS "__ggsql_stat_pos2", grid."__ggsql_aes_pos1__" AS "__ggsql_aes_pos1__", SUM(data.weight * ((EXP(-0.5 * (grid.x - data.val) * (grid.x - data.val) / (bandwidth.bw * bandwidth.bw))) * 0.3989422804014327)) / MIN(bandwidth.bw) AS "__ggsql_stat_intensity", SUM(data.weight) AS "__norm" FROM data INNER JOIN bandwidth ON (data."__ggsql_aes_pos1__" IS NOT DISTINCT FROM bandwidth."__ggsql_aes_pos1__") INNER JOIN grid ON (grid."__ggsql_aes_pos1__" IS NOT DISTINCT FROM data."__ggsql_aes_pos1__") GROUP BY grid.x, grid."__ggsql_aes_pos1__" ) AS "__ggsql_kde__") AS "__ggsql_stat__";

-- case: filter_layer
