SELECT * FROM (SELECT * FROM box_data) AS "__schema__" LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "grp" AS "__ggsql_aes_pos1__", "mixed Case" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") SELECT MIN("grp") AS "grp", MIN("mixed Case") AS "mixed Case" FROM "__ggsql_source__" UNION ALL SELECT MAX("grp") AS "grp", MAX("mixed Case") AS "mixed Case" FROM "__ggsql_source__";
