(cnt - 1)) THEN __val END) + (MAX(CASE WHEN rn = 1 + CEIL(0.75 * (cnt - 1)) THEN __val END) - MAX(CASE WHEN rn = 1 + FLOOR(0.75 * (cnt - 1)) THEN __val END)) * MAX(0.75 * (cnt - 1) - FLOOR(0.75 * (cnt - 1))) FROM (SELECT "__ggsql_aes_pos2__" AS __val, ROW_NUMBER() OVER (PARTITION BY "__ggsql_aes_pos1__" ORDER BY "__ggsql_aes_pos2__") AS rn, COUNT(*) OVER (PARTITION BY "__ggsql_aes_pos1__" ) AS cnt, "__ggsql_aes_pos1__" FROM (SELECT *, "grp" AS "__ggsql_aes_pos1__", "mixed Case" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos2__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_pos1__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_pos1__")) AS q3 FROM (SELECT *, "grp" AS "__ggsql_aes_pos1__", "mixed Case" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") AS "__ggsql_qt__" WHERE "__ggsql_aes_pos2__" IS NOT NULL GROUP BY "__ggsql_aes_pos1__") AS "__ggsql_fn__" ), outliers AS ( SELECT raw."__ggsql_aes_pos2__" AS value, 'outlier' AS type, raw."__ggsql_aes_pos1__" AS "__ggsql_aes_pos1__" FROM (SELECT *, "grp" AS "__ggsql_aes_pos1__", "mixed Case" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") AS "raw" JOIN summary ON raw."__ggsql_aes_pos1__" = summary."__ggsql_aes_pos1__" WHERE raw."__ggsql_aes_pos2__" NOT BETWEEN summary.lower AND summary.upper ) SELECT "__ggsql_aes_pos1__", 'lower_whisker' AS "__ggsql_stat_type", q1 AS "__ggsql_stat_value", lower AS "__ggsql_stat_value2" FROM summary UNION ALL SELECT "__ggsql_aes_pos1__", 'upper_whisker' AS "__ggsql_stat_type", q3 AS "__ggsql_stat_value", upper AS "__ggsql_stat_value2" FROM summary UNION ALL SELECT "__ggsql_aes_pos1__", 'box' AS "__ggsql_stat_type", q1 AS "__ggsql_stat_value", q3 AS "__ggsql_stat_value2" FROM summary UNION ALL SELECT "__ggsql_aes_pos1__", 'median' AS "__ggsql_stat_type", median AS "__ggsql_stat_value", NULL AS "__ggsql_stat_value2" FROM summary UNION ALL SELECT "__ggsql_aes_pos1__", type AS "__ggsql_stat_type", value AS "__ggsql_stat_value", NULL AS "__ggsql_stat_value2" FROM outliers) AS "__ggsql_stat__";

